package org.icu.sepsis.deterioration;
import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.util.*;import org.icu.sepsis.domain.Domain.Observation;import org.junit.jupiter.api.Test;
class HourlyUrineAssessmentTest {
 final Instant now=Instant.parse("2026-11-20T08:00:00Z");
 List<Observation> rows(int hours,double hourly){var rows=new ArrayList<Observation>();var w=new Observation();w.parameterCode="WEIGHT";w.value=70d;w.unit="kg";w.qualityStatus="valid";w.eventTime=now.minus(Duration.ofDays(2));rows.add(w);for(int i=0;i<hours;i++){var o=new Observation();o.parameterCode="URINE_OUTPUT";o.sourceParameterCode="param_niaoLiang";o.value=hourly;o.unit="ml";o.qualityStatus="valid";o.eventTime=now.minus(Duration.ofHours(i));rows.add(o);}return rows;}
 @Test void sixTwelveAndTwentyFourHourCandidatesUseIndependentCoverage(){for(int h:new int[]{6,12,24}){var r=HourlyUrineAssessment.evaluate(rows(h,h==24?10:20),now,true);assertEquals("candidate",r.get("status"));assertEquals(h==6?1:h==12?2:3,r.get("stageReference"));}}
 @Test void anuriaNeedsActualZeroRecords(){assertEquals(3,HourlyUrineAssessment.evaluate(rows(12,0),now,true).get("stageReference"));var missing=rows(12,0);missing.remove(3);var r=HourlyUrineAssessment.evaluate(missing,now,true);assertNotEquals(3,r.get("stageReference"));}
 @Test void gapsAndConflictingDuplicatesAreNeverFilledOrSelected(){var missing=rows(6,20);missing.remove(3);assertEquals("unknown",HourlyUrineAssessment.evaluate(missing,now,true).get("status"));var conflict=rows(6,20);var duplicate=rows(1,90).get(1);conflict.add(duplicate);assertEquals("unknown",HourlyUrineAssessment.evaluate(conflict,now,true).get("status"));}
 @Test void laterWeightAndWrongUnitsCannotBeUsed(){var later=rows(6,20);later.get(0).eventTime=now;assertEquals("unknown",HourlyUrineAssessment.evaluate(later,now,true).get("status"));var wrong=rows(6,20);wrong.get(1).unit="ml/day";assertEquals("unknown",HourlyUrineAssessment.evaluate(wrong,now,true).get("status"));}
 @Test void thresholdEqualityIsNotLowAndFutureOrStaleDataCannotCount(){assertEquals("not_triggered",HourlyUrineAssessment.evaluate(rows(6,35),now,true).get("status"));assertEquals("unknown",HourlyUrineAssessment.evaluate(rows(6,20),now.plus(Duration.ofHours(2)),true).get("status"));assertEquals("unknown",HourlyUrineAssessment.evaluate(rows(6,20),now,false).get("status"));}
 @Test void duplicateIdenticalRowsCountOnceAndUnconfirmedAliasDoesNotCount(){var r=rows(6,20);r.add(r.get(1));assertEquals(1,HourlyUrineAssessment.evaluate(r,now,true).get("stageReference"));for(var o:r)if(o.sourceParameterCode!=null)o.sourceParameterCode="param_urine";assertEquals("unknown",HourlyUrineAssessment.evaluate(r,now,true).get("status"));}
}
